q2 := months[4:7] fmt.Println(q2) summer := months[6:9] fmt.Println(summer)
fmt.Println(len(q2)) fmt.Println(cap(q2)) fmt.Println(len(summer)) fmt.Println(cap(summer))
newslice := q2[:6] fmt.Println(newslice)
org := []int{1, 2, 3, 4, 5, 6, 7, 8} fmt.Println(org) reverseSlice(org) fmt.Println(org)
fmt.Println("一个零值的slice等于nil。一个nil值的slice并没有底层数组") var s []int fmt.Println(s) fmt.Println(s == nil)
fmt.Println("nil slice 的长度和容量都为0") var nilSlice []int fmt.Println(len(nilSlice)) fmt.Println(cap(nilSlice)) fmt.Println(" 空slice 的长度和容量都为0") var emptySlice = []int{} fmt.Println(len(emptySlice)) fmt.Println(cap(emptySlice))
}
